#include <bits/stdc++.h>
using namespace std;

int main() {
    string s;
    cin >> s;
    int n = s.size();
    vector<long long> seen(2 * n + 1, 0);   // running totals from -n to n, shifted by n
    int cur = n;
    seen[cur] = 1;                          // the empty prefix
    long long answer = 0;
    for (char c : s) {
        cur += (c == '1') ? 1 : -1;
        answer += seen[cur]++;
    }
    cout << answer << "\n";
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    string s;
    cin >> s;
    int n = s.size();
    long long count = 0;
    for (int centre = 0; centre < 2 * n - 1; centre++) {
        int l = centre / 2, r = l + centre % 2;        // even centre: on a letter; odd centre: between two
        while (l >= 0 && r < n && s[l] == s[r]) { count++; l--; r++; }
    }
    cout << count << "\n";
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    scanf("%d", &n);
    vector<vector<int>> adj(n + 1);
    for (int i = 0; i < n - 1; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        adj[a].push_back(b);
        adj[b].push_back(a);
    }
    vector<int> parent(n + 1, 0), order = {1};
    parent[1] = -1;
    for (size_t i = 0; i < order.size(); i++)           // top-down order from the root
        for (int u : adj[order[i]])
            if (u != parent[order[i]]) { parent[u] = order[i]; order.push_back(u); }
    vector<int> take(n + 1, 1), skip(n + 1, 0);
    for (int i = n - 1; i >= 1; i--) {                    // children before parents
        int v = order[i], p = parent[v];
        take[p] += skip[v];
        skip[p] += max(take[v], skip[v]);
    }
    printf("%d\n", max(take[1], skip[1]));
}

#include <bits/stdc++.h>
using namespace std;

long long ways[20][200];   // ways[k][s]: k free digits with digit sum s

int main() {
    ways[0][0] = 1;
    for (int k = 1; k < 20; k++)
        for (int s = 0; s < 200; s++)
            for (int d = 0; d <= 9 && d <= s; d++) ways[k][s] += ways[k - 1][s - d];
    long long N;
    int S;
    cin >> N >> S;
    string digits = to_string(N);
    int len = digits.size(), used = 0;
    long long total = 0;
    for (int i = 0; i < len; i++) {
        int here = digits[i] - '0';
        for (int d = 0; d < here; d++)               // smaller digit here, everything after is free
            if (S - used - d >= 0) total += ways[len - i - 1][S - used - d];
        used += here;
    }
    if (used == S) total++;                           // N itself
    cout << total << "\n";                            // 0 is never counted because S >= 1
}
